/*
 * The images are generated by data/jp2/gen.py the matching checks are
 * implemented in pixmap_gen.h.
 */

#include <string.h>
#include <errno.h>
#include <math.h>

#include <loaders/gp_loaders.h>

#include "tst_test.h"
#include "pixmap_gen.h"

#define W 16
#define H 12

struct jp2_test {
	const char *img;
	gp_pixel_type pixel_type;
	gp_pixel (*exp)(gp_coord x, gp_coord y);
};

static int test_load_jp2(struct jp2_test *t)
{
	gp_pixmap *img;
	int ret;

	errno = 0;

	img = gp_load_jp2(t->img, NULL);
	if (!img) {
		switch (errno) {
		case ENOSYS:
			tst_msg("Not Implemented");
			return TST_SKIPPED;
		default:
			tst_msg("Got %s", strerror(errno));
			return TST_FAILED;
		}
	}

	ret = tst_pixmap_check(img, W, H, t->pixel_type, t->exp);

	gp_pixmap_free(img);
	return ret;
}

#define JP2_TEST(tname, img, ptype, exp) \
	{.name = tname, \
	 .tst_fn = test_load_jp2, \
	 .res_path = "data/jp2/valid/", \
	 .data = &(struct jp2_test){img, ptype, exp}, \
	 .flags = TST_TMPDIR | TST_CHECK_MALLOC}

const struct tst_suite tst_suite = {
	.suite_name = "JPEG 2000",
	.tests = {
		JP2_TEST("JP2 RGB", "rgb.jp2", GP_PIXEL_RGB888, exp_rgb),
		JP2_TEST("J2K codestream RGB", "rgb.j2k", GP_PIXEL_RGB888, exp_rgb),
		JP2_TEST("JP2 Gray", "gray.jp2", GP_PIXEL_G8, exp_gray),
		JP2_TEST("JP2 Gray 16bit", "gray16.jp2", GP_PIXEL_G8, exp_gray),
		JP2_TEST("JP2 Subsampled", "sub.jp2", GP_PIXEL_RGB888, exp_rgb),
		JP2_TEST("JP2 Gray 4bit", "gray4.jp2", GP_PIXEL_G8, exp_gray4),
		JP2_TEST("JP2 sYCC", "sycc.jp2", GP_PIXEL_RGB888, exp_sycc),
		JP2_TEST("JP2 CMYK", "cmyk.jp2", GP_PIXEL_CMYK8888, exp_cmyk),
		{.name = NULL},
	}
};
